 "content": "def transform(grid):
    h, w = len(grid), len(grid[0])
    # Solid horizontal color bands encode the repeating row palette. Use each
    # distinct band color once in reverse band order, then repeat vertically.
    bands = []
    for row in grid:
        if row and row[0] != 0 and all(v == row[0] for v in row):
            if row[0] not in bands:
                bands.append(row[0])
    if not bands:
        return [row[:] for row in grid]
    pattern = list(reversed(bands))
    return [[pattern[r % len(pattern)]] * w for r in range(h)]

